import { shuffle } from '@/config'
import { originToUsable, TUnPost } from '@/data/posts'
import { TPost } from '@/types'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useEffect, useRef, useState } from 'react'

const api = import.meta.env.VITE_API_NEWS

const LS_PREFIX = 'lp_cached_'
const STALE_THRESHOLD_MS = 10 * 60 * 1000 // 10 minutes

function getLsKey(lang: string, page?: string, rand?: boolean): string {
  return `${LS_PREFIX}${lang}_${page ?? '1'}_${!!rand}`
}

function getLastFetchTime(key: string): number | null {
  try {
    const val = localStorage.getItem(key)
    if (!val) return null
    const ts = Number(val)
    return Number.isFinite(ts) ? ts : null
  } catch {
    return null
  }
}

function setLastFetchTime(key: string): void {
  try {
    localStorage.setItem(key, String(Date.now()))
  } catch {
    // ignore — private browsing, quota, etc.
  }
}

function transformResponse(
  unformatedPosts: TUnPost[],
  rand?: boolean,
): TPost[] {
  const posts: TPost[] = unformatedPosts.map((post) => originToUsable(post))
  return rand ? shuffle(posts) : posts
}

export const useGetLastPost = (
  lang: 'fr' | 'ar',
  page?: string,
  rand?: boolean,
  bgRefresh?: boolean,
) => {
  const queryClient = useQueryClient()
  const hasRefreshed = useRef(false)
  const [isBackgroundRefreshing, setIsBackgroundRefreshing] = useState(false)
  const lsKey = getLsKey(lang, page, rand)

  // Reset refresh flag when params change (e.g. pagination)
  useEffect(() => {
    hasRefreshed.current = false
  }, [lang, page, rand])

  const query = useQuery({
    enabled: !!lang,
    staleTime: rand ? 1000 * 60 : 1000 * 260,
    queryKey: ['last', { lang, page, rand: !!rand }],
    queryFn: async () => {
      const response = await fetch(`${api}/lastnews?lang=${lang}&p=${page}`)
      if (!response.ok) {
        throw new Error('faild to fetch posts')
      }

      const { results: unformatedPosts, total }: categorieResponse =
        await response.json()

      const posts = transformResponse(unformatedPosts, rand)
      return { posts, total }
    },
  })

  // Background refresh for returning users (opt-in via bgRefresh param):
  // SW StaleWhileRevalidate serves stale cache instantly on return visits.
  // This effect checks if 10+ minutes passed since the last fetch. If so,
  // it fires a cache-busted 2nd fetch to get fresh data, then swaps it in
  // via setQueryData and updates the timestamp.
  useEffect(() => {
    if (!bgRefresh) return
    if (hasRefreshed.current) return
    if (!query.data || query.isFetching) return

    const lastFetch = getLastFetchTime(lsKey)

    if (lastFetch === null) {
      // First visit for this query — store timestamp, data is already fresh
      setLastFetchTime(lsKey)
      return
    }

    const elapsed = Date.now() - lastFetch
    if (elapsed < STALE_THRESHOLD_MS) {
      // Less than 10 min since last fetch — data is fresh enough
      return
    }

    // 10+ min passed — data is likely stale from SW cache, fetch fresh
    hasRefreshed.current = true
    setIsBackgroundRefreshing(true)

    fetch(`${api}/lastnews?lang=${lang}&p=${page}&_cb=${Date.now()}`)
      .then((res) => {
        if (!res.ok) throw new Error('background refresh failed')
        return res.json()
      })
      .then(({ results: unformatedPosts, total }: categorieResponse) => {
        const posts = transformResponse(unformatedPosts, rand)
        if (posts.length > 0) {
          queryClient.setQueryData(['last', { lang, page, rand: !!rand }], {
            posts,
            total,
          })
        }
        setLastFetchTime(lsKey)
      })
      .catch(() => {
        // Silently fail — user keeps seeing cached data
      })
      .finally(() => {
        setIsBackgroundRefreshing(false)
      })
  }, [
    bgRefresh,
    query.data,
    query.isFetching,
    lang,
    page,
    rand,
    lsKey,
    queryClient,
  ])

  return { ...query, isBackgroundRefreshing }
}

export interface categorieResponse {
  page: number
  pageSize: number
  total: number
  results: TUnPost[]
}
